        for j in range(n+1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif S[i-1] == T[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

